import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';

const Login = ({ setAuth }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!email || !password) {
      setError('Please enter both email and password.');
      return;
    }

    localStorage.setItem('campusmart_auth', 'true');
    setAuth(true);
    navigate('/dashboard');
  };

  return (
    <main className="page-shell auth-page">
      <section className="auth-card">
        <div className="auth-copy">
          <p className="eyebrow">Welcome back</p>
          <h1>Sign in to CampusMart</h1>
          <p>Access your dashboard, manage listings, and browse the marketplace.</p>
        </div>

        <form onSubmit={handleSubmit} className="auth-form">
          {error && <div className="form-alert error-alert">{error}</div>}

          <label className="input-group">
            <span>Email</span>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="your@email.com"
            />
          </label>

          <label className="input-group">
            <span>Password</span>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="Enter your password"
            />
          </label>

          <button type="submit" className="gradient-btn">
            Sign In
          </button>

          <div className="form-footer">
            <Link to="/register" className="subtle-link">
              Create a new account
            </Link>
            <Link to="/" className="subtle-link">
              Forgot password?
            </Link>
          </div>
        </form>
      </section>
    </main>
  );
};

export default Login;
